"use client";

import {
    readExamMeta,
    readExamRecords,
    writeExamMeta,
    writeExamRecords,
} from "@/lib/exams/cache";
import { ensureNotificationPermission, notifyNewExams } from "@/lib/exams/notify";
import {
    parseWorkbookFromNotice,
    type ParsedExamRecord,
} from "@/lib/exams/parseWorkbook";
import { openExamPageInExtension, requestExamSync } from "@/lib/extensionBridge";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

type PlanFilter = "all" | "tentative" | "official";
type SortMode = "date-asc" | "date-desc" | "course-asc" | "student-asc";
type BannerTone = "info" | "success" | "warning" | "error";

type SearchToken = {
  raw: string;
  loose: string;
  compact: string;
};

type HeatmapBucket = {
  date: string;
  count: number;
  level: number;
};

function normalizeText(value: unknown) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeCompact(value: unknown) {
  return normalizeText(value).replace(/[^a-z0-9]/g, "");
}

function tokenizeQuery(query: string): SearchToken[] {
  return query
    .split(/[,;\n]+/)
    .map((part) => part.trim())
    .filter(Boolean)
    .map((raw) => ({
      raw,
      loose: normalizeText(raw),
      compact: normalizeCompact(raw),
    }));
}

function formatDate(value: string | null, locale = "vi-VN") {
  if (!value) return locale.startsWith("vi") ? "Chưa rõ ngày" : "Unknown date";
  const d = new Date(`${value}T00:00:00`);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleDateString(locale);
}

function formatDateTime(value: string | null, locale = "vi-VN") {
  if (!value) return locale.startsWith("vi") ? "Chưa có dữ liệu" : "No data";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString(locale);
}

function compareDateTimeAsc(a: ParsedExamRecord, b: ParsedExamRecord) {
  const av = `${a.examDate || "9999-12-31"} ${a.startTime || "23:59"}`;
  const bv = `${b.examDate || "9999-12-31"} ${b.startTime || "23:59"}`;
  return av.localeCompare(bv);
}

function compareDateTimeDesc(a: ParsedExamRecord, b: ParsedExamRecord) {
  return compareDateTimeAsc(b, a);
}

function getInitialPlan(searchParams: ReturnType<typeof useSearchParams>): PlanFilter {
  const plan = searchParams.get("plan");
  if (plan === "tentative" || plan === "official") return plan;
  return "all";
}

function getInitialSort(searchParams: ReturnType<typeof useSearchParams>): SortMode {
  const sort = searchParams.get("sort");
  if (
    sort === "date-asc" ||
    sort === "date-desc" ||
    sort === "course-asc" ||
    sort === "student-asc"
  ) {
    return sort;
  }
  return "date-asc";
}

function buildSearchIndex(record: ParsedExamRecord) {
  const looseHaystacks = [
    record.courseCode,
    record.courseName,
    record.studentId,
    record.studentName,
    record.classCourse,
    record.classStudent,
    record.birthDate,
    record.examDate,
    record.room,
    record.campus,
    record.noticeTitle,
    record.examMetaRaw,
    record.attachmentName,
    record.publishedAtRaw,
  ].map(normalizeText);

  const compactHaystacks = [
    record.courseCode,
    record.studentId,
    record.classCourse,
    record.classStudent,
    record.room,
  ].map(normalizeCompact);

  return { looseHaystacks, compactHaystacks };
}

function getDayDiff(dateValue: string | null) {
  if (!dateValue) return null;

  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const target = new Date(`${dateValue}T00:00:00`);

  if (Number.isNaN(target.getTime())) return null;

  const msPerDay = 24 * 60 * 60 * 1000;
  return Math.round((target.getTime() - today.getTime()) / msPerDay);
}

function getCountdownLabel(
  dateValue: string | null,
  t: (key: string, options?: Record<string, unknown>) => string
) {
  const diff = getDayDiff(dateValue);

  if (diff === null) return t("exams.labels.unknownDate");
  if (diff < 0) return t("exams.labels.passedDays", { count: Math.abs(diff) });
  if (diff === 0) return t("exams.labels.today");
  if (diff === 1) return t("exams.labels.tomorrow");
  return t("exams.labels.remainingDays", { count: diff });
}

function getStatusTone(dateValue: string | null) {
  const diff = getDayDiff(dateValue);

  if (diff === null) return "app-badge-empty";
  if (diff < 0) return "app-pill";
  if (diff <= 3) return "app-pill-danger";
  if (diff <= 7) return "app-pill-warning";
  return "app-pill-success";
}

function makeHeatmapBuckets(records: ParsedExamRecord[]): HeatmapBucket[] {
  const countMap = new Map<string, number>();

  for (const record of records) {
    const key = record.examDate || "unknown";
    countMap.set(key, (countMap.get(key) || 0) + 1);
  }

  const validDates = Array.from(countMap.keys())
    .filter((x) => x !== "unknown")
    .sort((a, b) => a.localeCompare(b));

  if (!validDates.length) return [];

  const maxCount = Math.max(...validDates.map((d) => countMap.get(d) || 0));

  return validDates.map((date) => {
    const count = countMap.get(date) || 0;
    const ratio = maxCount > 0 ? count / maxCount : 0;

    let level = 1;
    if (ratio >= 0.75) level = 4;
    else if (ratio >= 0.5) level = 3;
    else if (ratio >= 0.25) level = 2;

    return { date, count, level };
  });
}

function getHeatmapClass(level: number) {
  if (level === 4) return "bg-[var(--danger)]/90";
  if (level === 3) return "bg-[var(--warning)]/85";
  if (level === 2) return "bg-[var(--accent)]/75";
  return "bg-[var(--accent)]/35";
}

function getNewestRecordsForNotify(
  previousIds: string[],
  nextRecords: ParsedExamRecord[],
  limit = 5
) {
  const known = new Set(previousIds);
  const news = nextRecords.filter((record) => !known.has(record.id));
  news.sort(compareDateTimeAsc);
  return news.slice(0, limit);
}

function getBannerClass(tone: BannerTone) {
  if (tone === "success") {
    return "border border-[var(--success)]/20 bg-[var(--success)]/10 text-[var(--success)]";
  }
  if (tone === "warning") {
    return "border border-[var(--warning)]/20 bg-[var(--warning)]/10 text-[var(--warning)]";
  }
  if (tone === "error") {
    return "border border-[var(--danger)]/20 bg-[var(--danger-soft)] text-[var(--danger)]";
  }
  return "border border-[var(--accent)]/20 bg-[var(--accent)]/10 text-[var(--accent)]";
}

function mapSyncErrorMessage(
  raw: string,
  t: (key: string, options?: Record<string, unknown>) => string
) {
  const text = String(raw || "").trim();
  const normalized = text.toLowerCase();

  if (
    normalized.includes("receiving end does not exist") ||
    normalized.includes("could not establish connection")
  ) {
    return t("exams.sync.errors.extensionReload");
  }

  if (normalized.includes("timeout")) {
    return t("exams.sync.errors.timeout");
  }

  if (normalized.includes("chrome.runtime.sendmessage unavailable")) {
    return t("exams.sync.errors.extensionUnavailable");
  }

  if (normalized.includes("empty response from extension")) {
    return t("exams.sync.errors.emptyResponse");
  }

  if (normalized.includes("không scrape được danh sách thi")) {
    return t("exams.sync.errors.scrapeFailed");
  }

  if (normalized.includes("attachment fetch failed")) {
    return t("exams.sync.errors.attachmentFailed");
  }

  if (normalized.includes("fetch failed")) {
    return t("exams.sync.errors.portalFetchFailed");
  }

  return text || t("exams.sync.errors.unknown");
}

function exportExamCsv(records: ParsedExamRecord[], locale: string, fileLabel: string) {
  const rows = [
    [
      "planType",
      "courseCode",
      "courseName",
      "examDate",
      "startTime",
      "endTime",
      "room",
      "campus",
      "studentId",
      "studentName",
      "classCourse",
      "classStudent",
      "birthDate",
      "publishedAtRaw",
      "attachmentName",
      "noticeTitle",
      "detailUrl",
      "attachmentUrl",
      "examMetaRaw",
      "note",
    ],
    ...records.map((record) => [
      record.planType,
      record.courseCode || "",
      record.courseName || "",
      record.examDate || "",
      record.startTime || "",
      record.endTime || "",
      record.room || "",
      record.campus || "",
      record.studentId || "",
      record.studentName || "",
      record.classCourse || "",
      record.classStudent || "",
      record.birthDate || "",
      record.publishedAtRaw || "",
      record.attachmentName || "",
      record.noticeTitle || "",
      record.detailUrl || "",
      record.attachmentUrl || "",
      record.examMetaRaw || "",
      record.note || "",
    ]),
  ];

  const escapeCsv = (value: string) => {
    const safe = String(value ?? "");
    if (safe.includes('"') || safe.includes(",") || safe.includes("\n")) {
      return `"${safe.replace(/"/g, '""')}"`;
    }
    return safe;
  };

  const csv = rows.map((row) => row.map(escapeCsv).join(",")).join("\n");
  const blob = new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8;" });

  const fileDate = new Date().toLocaleDateString(locale).replace(/[^\d]+/g, "-");
  const filename = `${fileLabel}-${fileDate}.csv`;

  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

export default function ExamsPage() {
  const { t, i18n } = useTranslation();
  const locale = i18n.language?.startsWith("vi") ? "vi-VN" : "en-US";

  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [records, setRecords] = useState<ParsedExamRecord[]>([]);
  const [query, setQuery] = useState("");
  const [planFilter, setPlanFilter] = useState<PlanFilter>(getInitialPlan(searchParams));
  const [sortMode, setSortMode] = useState<SortMode>(getInitialSort(searchParams));
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastSyncedAt, setLastSyncedAt] = useState<string | null>(null);
  const [lastNoticeCount, setLastNoticeCount] = useState(0);
  const [notifyPermission, setNotifyPermission] = useState<NotificationPermission | "unsupported">(
    "unsupported"
  );
  const [bannerTone, setBannerTone] = useState<BannerTone>("info");
  const [bannerText, setBannerText] = useState<string>("");
  const [onlyUpcoming, setOnlyUpcoming] = useState(false);
  const [visibleGroupsLimit, setVisibleGroupsLimit] = useState(8);

  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const [cachedRecords] = await Promise.all([readExamRecords()]);
        const meta = readExamMeta();

        if (cancelled) return;

        setRecords(cachedRecords);
        setLastSyncedAt(meta.lastSyncedAt);
        setLastNoticeCount(meta.lastNoticeCount);

        const permission = await ensureNotificationPermission();
        if (!cancelled) setNotifyPermission(permission);

        if (!cachedRecords.length) {
          setBannerTone("info");
          setBannerText(t("exams.sync.idleHelp"));
        } else {
          setBannerTone("success");
          setBannerText(
            t("exams.sync.cachedReady", {
              count: cachedRecords.length,
              time: meta.lastSyncedAt
                ? formatDateTime(meta.lastSyncedAt, locale)
                : t("exams.sync.noSyncYet"),
            })
          );
        }
      } catch {
        if (!cancelled) {
          setBannerTone("warning");
          setBannerText(t("exams.sync.cacheFallback"));
        }
      }
    }

    boot();

    return () => {
      cancelled = true;
    };
  }, [locale, t]);

  useEffect(() => {
    setPlanFilter(getInitialPlan(searchParams));
    setSortMode(getInitialSort(searchParams));
  }, [searchParams]);

  useEffect(() => {
    setVisibleGroupsLimit(8);
  }, [query, planFilter, sortMode, onlyUpcoming]);

  const tokens = useMemo(() => tokenizeQuery(query), [query]);

  const indexedRecords = useMemo(
    () =>
      records.map((record) => ({
        record,
        index: buildSearchIndex(record),
      })),
    [records]
  );

  const filtered = useMemo(() => {
    let next = indexedRecords;

    if (planFilter !== "all") {
      next = next.filter(({ record }) => record.planType === planFilter);
    }

    if (onlyUpcoming) {
      next = next.filter(({ record }) => {
        const diff = getDayDiff(record.examDate);
        return diff !== null && diff >= 0;
      });
    }

    if (tokens.length) {
      next = next.filter(({ index }) => {
        return tokens.some((token) => {
          const looseMatch = index.looseHaystacks.some((value) => value.includes(token.loose));
          const compactMatch = token.compact
            ? index.compactHaystacks.some((value) => value.includes(token.compact))
            : false;
          return looseMatch || compactMatch;
        });
      });
    }

    const mapped = next.map((x) => x.record);

    if (sortMode === "date-asc") mapped.sort(compareDateTimeAsc);
    else if (sortMode === "date-desc") mapped.sort(compareDateTimeDesc);
    else if (sortMode === "course-asc") {
      mapped.sort((a, b) =>
        `${a.courseCode} ${a.courseName || ""}`.localeCompare(
          `${b.courseCode} ${b.courseName || ""}`,
          i18n.language?.startsWith("vi") ? "vi" : "en"
        )
      );
    } else if (sortMode === "student-asc") {
      mapped.sort((a, b) =>
        `${a.studentName || ""} ${a.studentId || ""}`.localeCompare(
          `${b.studentName || ""} ${b.studentId || ""}`,
          i18n.language?.startsWith("vi") ? "vi" : "en"
        )
      );
    }

    return mapped;
  }, [i18n.language, indexedRecords, onlyUpcoming, planFilter, sortMode, tokens]);

  const grouped = useMemo(() => {
    const map = new Map<string, ParsedExamRecord[]>();

    for (const record of filtered) {
      const key = record.examDate || "unknown";
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(record);
    }

    return Array.from(map.entries());
  }, [filtered]);

  const visibleGroups = useMemo(
    () => grouped.slice(0, visibleGroupsLimit),
    [grouped, visibleGroupsLimit]
  );

  const hasMoreGroups = visibleGroupsLimit < grouped.length;

  const stats = useMemo(() => {
    const official = records.filter((r) => r.planType === "official").length;
    const tentative = records.filter((r) => r.planType === "tentative").length;
    const uniqueCourses = new Set(records.map((r) => r.courseCode).filter(Boolean)).size;
    const uniqueStudents = new Set(records.map((r) => r.studentId).filter(Boolean)).size;
    const uniqueDays = new Set(records.map((r) => r.examDate).filter(Boolean)).size;
    const upcoming = records.filter((r) => {
      const diff = getDayDiff(r.examDate);
      return diff !== null && diff >= 0;
    }).length;

    return {
      total: records.length,
      official,
      tentative,
      uniqueCourses,
      uniqueStudents,
      upcoming,
      visible: filtered.length,
      uniqueDays,
    };
  }, [filtered.length, records]);

  const heatmapDays = useMemo(() => makeHeatmapBuckets(records), [records]);

  const heatmapHighlights = useMemo(() => {
    return [...heatmapDays]
      .sort((a, b) => b.count - a.count || a.date.localeCompare(b.date))
      .slice(0, 8);
  }, [heatmapDays]);

  const nextUpcoming = useMemo(() => {
    return [...records]
      .filter((record) => {
        const diff = getDayDiff(record.examDate);
        return diff !== null && diff >= 0;
      })
      .sort(compareDateTimeAsc)
      .slice(0, 10);
  }, [records]);

  const topCourses = useMemo(() => {
    const map = new Map<string, { code: string; name: string | null; count: number }>();

    for (const record of filtered) {
      const key = record.courseCode || record.noticeTitle || "unknown";
      const current = map.get(key);

      if (current) {
        current.count += 1;
      } else {
        map.set(key, {
          code: record.courseCode || t("exams.labels.unknownCourseCode"),
          name: record.courseName || null,
          count: 1,
        });
      }
    }

    return Array.from(map.values())
      .sort((a, b) => b.count - a.count || a.code.localeCompare(b.code))
      .slice(0, 8);
  }, [filtered, t]);

  function replaceQueryParams(nextParams: { plan?: PlanFilter; sort?: SortMode }) {
    const next = new URLSearchParams(searchParams.toString());

    if (nextParams.plan) {
      if (nextParams.plan === "all") next.delete("plan");
      else next.set("plan", nextParams.plan);
    }

    if (nextParams.sort) {
      if (nextParams.sort === "date-asc") next.delete("sort");
      else next.set("sort", nextParams.sort);
    }

    const qs = next.toString();
    router.replace(qs ? `${pathname}?${qs}` : pathname);
  }

  function updatePlanFilter(value: PlanFilter) {
    setPlanFilter(value);
    replaceQueryParams({ plan: value });
  }

  function updateSortMode(value: SortMode) {
    setSortMode(value);
    replaceQueryParams({ sort: value });
  }

  function resetFilters() {
    setQuery("");
    setOnlyUpcoming(false);
    setPlanFilter("all");
    setSortMode("date-asc");
    router.replace(pathname);
  }

  async function handleSync() {
    setSyncing(true);
    setError(null);
    setBannerTone("info");
    setBannerText(t("exams.sync.preparing"));

    try {
      const previousMeta = readExamMeta();

      setBannerText(t("exams.sync.portalPreparing"));
      await openExamPageInExtension().catch(() => null);

      setBannerText(t("exams.sync.fetchingPortal"));
      const extensionRes = await requestExamSync({
        maxPages: 3,
        maxItems: 40,
      });

      if (!extensionRes.ok) {
        const friendly = mapSyncErrorMessage(extensionRes.error || "", t);
        setError(friendly);
        setBannerTone("error");
        setBannerText(friendly);
        return;
      }

      setBannerText(t("exams.sync.parsingWorkbook"));

      const parsedChunks = await Promise.all(
        extensionRes.payload.notices.map(async (notice) => parseWorkbookFromNotice(notice))
      );

      const parsedRecords = parsedChunks.flat();

      const deduped = Array.from(
        new Map(parsedRecords.map((record) => [record.id, record])).values()
      ).sort(compareDateTimeAsc);

      setRecords(deduped);
      setLastSyncedAt(extensionRes.payload.scrapedAt);
      setLastNoticeCount(extensionRes.payload.notices.length);

      await writeExamRecords(deduped);

      const newRecordsForNotify = getNewestRecordsForNotify(
        previousMeta.lastNotifiedIds,
        deduped,
        5
      );

      const nextMeta = {
        lastSyncedAt: extensionRes.payload.scrapedAt,
        lastNoticeCount: extensionRes.payload.notices.length,
        lastNotifiedIds: deduped.map((x) => x.id).slice(0, 300),
      };

      writeExamMeta(nextMeta);

      if (newRecordsForNotify.length) {
        const permission = await ensureNotificationPermission();
        setNotifyPermission(permission);

        if (permission === "granted") {
          notifyNewExams(newRecordsForNotify);
        }
      }

      setBannerTone("success");
      setBannerText(
        t("exams.sync.successDetailed", {
          totalRecords: deduped.length,
          totalNotices: extensionRes.payload.notices.length,
        })
      );
    } catch (e) {
      const friendly = mapSyncErrorMessage(String((e as Error)?.message || e), t);
      setError(friendly);
      setBannerTone("error");
      setBannerText(friendly);
    } finally {
      setSyncing(false);
    }
  }

  async function handleEnableNotify() {
    const permission = await ensureNotificationPermission();
    setNotifyPermission(permission);

    if (permission === "granted") {
      setBannerTone("success");
      setBannerText(t("exams.notify.enabled"));
    } else if (permission === "denied") {
      setBannerTone("warning");
      setBannerText(t("exams.notify.denied"));
    } else {
      setBannerTone("info");
      setBannerText(t("exams.notify.pending"));
    }
  }

  async function handleOpenPdaotao() {
    const res = await openExamPageInExtension();

    if (!res.ok) {
      window.open("https://pdaotao.duytan.edu.vn/EXAM_LIST/?page=1&lang=VN", "_blank");
      setBannerTone("info");
      setBannerText(t("exams.sync.portalOpenedFallback"));
      return;
    }

    setBannerTone("info");
    setBannerText(t("exams.sync.portalOpened"));
  }

  function handleExportCsv() {
    exportExamCsv(filtered, locale, t("exams.export.fileName"));
    setBannerTone("success");
    setBannerText(t("exams.export.done", { count: filtered.length }));
  }

  return (
    <div className="space-y-6">
      <section className="app-section p-5 md:p-6">
        <div className="flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
          <div className="max-w-3xl">
            <div className="text-3xl font-bold tracking-tight">{t("exams.page.title")}</div>
            <div className="mt-2 text-sm app-text-muted">{t("exams.page.subtitle")}</div>
          </div>

          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={handleOpenPdaotao} className="app-btn">
              {t("exams.actions.openPortal")}
            </button>

            <button type="button" onClick={handleEnableNotify} className="app-btn">
              {notifyPermission === "granted"
                ? t("exams.actions.notifyEnabled")
                : notifyPermission === "denied"
                ? t("exams.actions.notifyBlocked")
                : t("exams.actions.enableNotify")}
            </button>

            <button type="button" onClick={handleExportCsv} className="app-btn">
              {t("exams.actions.exportCsv")}
            </button>

            <button
              type="button"
              onClick={handleSync}
              disabled={syncing}
              className="app-btn-primary"
            >
              {syncing ? t("exams.actions.syncing") : t("exams.actions.sync")}
            </button>
          </div>
        </div>

        <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4 2xl:grid-cols-8">
          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.totalRecords")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.total}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.visible")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.visible}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.uniqueDays")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.uniqueDays}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.courses")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.uniqueCourses}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.students")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.uniqueStudents}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.upcoming")}
            </div>
            <div className="mt-2 text-2xl font-bold">{stats.upcoming}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.official")}
            </div>
            <div className="mt-2 text-2xl font-bold text-[var(--success)]">{stats.official}</div>
          </div>

          <div className="app-panel p-4">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              {t("exams.stats.tentative")}
            </div>
            <div className="mt-2 text-2xl font-bold text-[var(--warning)]">
              {stats.tentative}
            </div>
          </div>
        </div>

        <div className="mt-5 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] p-4">
          <div className="grid gap-3 xl:grid-cols-[minmax(0,1.6fr)_220px_220px]">
            <label htmlFor="exam-search" className="sr-only">
              {t("exams.filters.searchLabel")}
            </label>
            <input
              id="exam-search"
              className="app-input"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={t("exams.filters.searchPlaceholder")}
            />

            <label htmlFor="exam-plan-filter" className="sr-only">
              {t("exams.filters.planLabel")}
            </label>
            <select
              id="exam-plan-filter"
              title={t("exams.filters.planLabel")}
              aria-label={t("exams.filters.planLabel")}
              className="app-input"
              value={planFilter}
              onChange={(e) =>
                updatePlanFilter(e.target.value as "all" | "tentative" | "official")
              }
            >
              <option value="all">{t("exams.filters.allTypes")}</option>
              <option value="official">{t("exams.filters.official")}</option>
              <option value="tentative">{t("exams.filters.tentative")}</option>
            </select>

            <label htmlFor="exam-sort-mode" className="sr-only">
              {t("exams.filters.sortLabel")}
            </label>
            <select
              id="exam-sort-mode"
              title={t("exams.filters.sortLabel")}
              aria-label={t("exams.filters.sortLabel")}
              className="app-input"
              value={sortMode}
              onChange={(e) =>
                updateSortMode(
                  e.target.value as "date-asc" | "date-desc" | "course-asc" | "student-asc"
                )
              }
            >
              <option value="date-asc">{t("exams.sort.dateAsc")}</option>
              <option value="date-desc">{t("exams.sort.dateDesc")}</option>
              <option value="course-asc">{t("exams.sort.courseAsc")}</option>
              <option value="student-asc">{t("exams.sort.studentAsc")}</option>
            </select>
          </div>

          <div className="mt-3 flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={() => setOnlyUpcoming((v) => !v)}
              className={[
                "rounded-full px-3 py-1.5 text-xs font-medium transition",
                onlyUpcoming ? "app-btn-primary" : "app-btn",
              ].join(" ")}
            >
              {t("exams.filters.onlyUpcoming")}
            </button>

            <button type="button" onClick={resetFilters} className="app-btn rounded-full px-3 py-1.5 text-xs">
              {t("exams.actions.resetFilters")}
            </button>

            {tokens.length ? (
              tokens.map((token) => (
                <span
                  key={token.raw}
                  className="inline-flex rounded-full app-pill px-3 py-1 text-xs font-medium"
                >
                  {token.raw}
                </span>
              ))
            ) : (
              <span className="text-xs app-text-muted">{t("exams.filters.tip")}</span>
            )}
          </div>

          <div className="mt-3 flex flex-wrap gap-x-6 gap-y-2 text-xs app-text-muted">
            <span>
              {lastSyncedAt
                ? t("exams.meta.lastSyncAt", {
                    time: formatDateTime(lastSyncedAt, locale),
                  })
                : t("exams.meta.noSyncYet")}
            </span>
            <span>{t("exams.meta.noticeCount", { count: lastNoticeCount })}</span>
            <span>{t("exams.meta.visibleCount", { count: stats.visible })}</span>
            <span>{t("exams.meta.groupCount", { count: grouped.length })}</span>
            <span>
              {t("exams.meta.notifyStatus", {
                status:
                  notifyPermission === "granted"
                    ? t("exams.notify.statusGranted")
                    : notifyPermission === "denied"
                    ? t("exams.notify.statusDenied")
                    : notifyPermission === "default"
                    ? t("exams.notify.statusDefault")
                    : t("exams.notify.statusUnsupported"),
              })}
            </span>
          </div>
        </div>

        <div className={`mt-4 rounded-2xl px-4 py-3 text-sm ${getBannerClass(bannerTone)}`}>
          <div className="font-medium">{bannerText || t("exams.sync.idleHelp")}</div>
          {!syncing ? <div className="mt-1 text-xs opacity-80">{t("exams.sync.hint")}</div> : null}
        </div>

        {error ? (
          <div className="mt-3 rounded-2xl border border-[var(--danger)]/20 bg-[var(--danger-soft)] px-4 py-3 text-sm text-[var(--danger)]">
            {error}
          </div>
        ) : null}
      </section>

      <section className="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]">
        <div className="app-section p-5 md:p-6">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <div className="text-lg font-semibold">{t("exams.insights.title")}</div>
              <div className="mt-1 text-sm app-text-muted">{t("exams.insights.subtitle")}</div>
            </div>
            <span className="inline-flex rounded-full app-pill px-3 py-1 text-xs font-medium">
              {t("exams.meta.groupCount", { count: grouped.length })}
            </span>
          </div>

          <div className="mt-5 grid gap-4 lg:grid-cols-2">
            <div className="rounded-2xl border border-[var(--border-main)] p-4">
              <div className="text-base font-semibold">{t("exams.insights.peakDays")}</div>
              <div className="mt-1 text-sm app-text-muted">{t("exams.insights.peakDaysHint")}</div>

              {heatmapHighlights.length === 0 ? (
                <div className="mt-4 rounded-2xl app-soft p-4 text-sm app-text-muted">
                  {t("exams.insights.noHeatmap")}
                </div>
              ) : (
                <div className="mt-4 space-y-3">
                  {heatmapHighlights.map((item) => (
                    <div key={item.date}>
                      <div className="mb-1 flex items-center justify-between gap-3 text-sm">
                        <span className="font-medium">{formatDate(item.date, locale)}</span>
                        <span className="app-text-muted">
                          {t("exams.insights.recordCount", { count: item.count })}
                        </span>
                      </div>
                      <div className="h-3 rounded-full bg-[var(--bg-soft)]">
                        <div
                          className={`h-3 rounded-full ${getHeatmapClass(item.level)}`}
                          style={{
                            width: `${Math.max(12, (item.count / Math.max(...heatmapHighlights.map((x) => x.count))) * 100)}%`,
                          }}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="rounded-2xl border border-[var(--border-main)] p-4">
              <div className="text-base font-semibold">{t("exams.insights.courseLoad")}</div>
              <div className="mt-1 text-sm app-text-muted">{t("exams.insights.courseLoadHint")}</div>

              {topCourses.length === 0 ? (
                <div className="mt-4 rounded-2xl app-soft p-4 text-sm app-text-muted">
                  {t("exams.insights.noCourseLoad")}
                </div>
              ) : (
                <div className="mt-4 space-y-3">
                  {topCourses.map((course) => (
                    <div
                      key={`${course.code}-${course.name || ""}`}
                      className="rounded-2xl bg-[var(--bg-soft)] p-3"
                    >
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0">
                          <div className="truncate font-semibold">{course.code}</div>
                          <div className="mt-1 truncate text-sm app-text-muted">
                            {course.name || "—"}
                          </div>
                        </div>
                        <span className="inline-flex rounded-full app-pill px-3 py-1 text-xs font-medium">
                          {course.count}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="app-section p-5 md:p-6">
          <div>
            <div className="text-base font-semibold">{t("exams.insights.timelineTitle")}</div>
            <div className="mt-1 text-sm app-text-muted">{t("exams.insights.timelineHint")}</div>
          </div>

          {nextUpcoming.length === 0 ? (
            <div className="mt-4 rounded-2xl app-soft p-4 text-sm app-text-muted">
              {t("exams.insights.noTimeline")}
            </div>
          ) : (
            <div className="mt-4 space-y-3">
              {nextUpcoming.map((record) => (
                <div
                  key={record.id}
                  className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-card-strong)] p-4"
                >
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div className="min-w-0">
                      <div className="font-semibold">
                        {record.courseCode || t("exams.labels.unknownCourseCode")}
                        <span className="app-text-muted font-normal">
                          {record.courseName ? ` • ${record.courseName}` : ""}
                        </span>
                      </div>

                      <div className="mt-1 text-sm app-text-muted">
                        {formatDate(record.examDate, locale)} •{" "}
                        {record.startTime || t("exams.labels.unknownTime")} •{" "}
                        {record.room || t("exams.labels.unknownRoom")}
                        {record.campus ? ` • ${record.campus}` : ""}
                      </div>

                      <div className="mt-2 text-xs app-text-muted">
                        {record.studentName || t("exams.labels.unknownStudent")}
                        {record.studentId ? ` • ${record.studentId}` : ""}
                      </div>
                    </div>

                    <span
                      className={[
                        "inline-flex rounded-full px-3 py-1 text-xs font-semibold",
                        getStatusTone(record.examDate),
                      ].join(" ")}
                    >
                      {getCountdownLabel(record.examDate, t)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      <section className="space-y-4">
        {grouped.length === 0 ? (
          <div className="app-section p-8 text-center">
            <div className="text-lg font-semibold">{t("exams.empty.title")}</div>
            <div className="mt-2 text-sm app-text-muted">{t("exams.empty.subtitle")}</div>
          </div>
        ) : (
          <>
            {visibleGroups.map(([dateKey, items]) => (
              <div key={dateKey} className="app-section overflow-hidden">
                <div className="border-b border-[var(--border-main)] px-5 py-4">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div>
                      <div className="text-lg font-semibold">{formatDate(dateKey, locale)}</div>
                      <div className="mt-1 text-sm app-text-muted">
                        {t("exams.table.recordCount", { count: items.length })}
                      </div>
                    </div>

                    <span
                      className={[
                        "inline-flex rounded-full px-3 py-1 text-xs font-semibold",
                        getStatusTone(dateKey),
                      ].join(" ")}
                    >
                      {getCountdownLabel(dateKey, t)}
                    </span>
                  </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="min-w-[1180px] w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--border-main)] bg-[var(--bg-soft)] text-left">
                        <th className="px-4 py-3 font-semibold">{t("exams.table.type")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.course")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.time")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.room")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.student")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.class")}</th>
                        <th className="px-4 py-3 font-semibold">{t("exams.table.source")}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {items.map((record) => (
                        <tr
                          key={record.id}
                          className="border-b border-[var(--border-main)]/70 align-top"
                        >
                          <td className="px-4 py-3">
                            <span
                              className={[
                                "inline-flex rounded-full px-2.5 py-1 text-xs font-semibold",
                                record.planType === "official"
                                  ? "app-pill-success"
                                  : "app-pill-warning",
                              ].join(" ")}
                            >
                              {record.planType === "official"
                                ? t("exams.filters.official")
                                : t("exams.filters.tentative")}
                            </span>
                          </td>

                          <td className="px-4 py-3">
                            <div className="font-semibold">
                              {record.courseCode || t("exams.labels.unknownCourseCode")}
                            </div>
                            <div className="mt-1 app-text-muted">
                              {record.courseName || record.noticeTitle}
                            </div>
                          </td>

                          <td className="px-4 py-3">
                            <div>{record.startTime || t("exams.labels.unknownTime")}</div>
                            <div className="mt-1 text-xs app-text-muted">
                              {record.examMetaRaw || ""}
                            </div>
                          </td>

                          <td className="px-4 py-3">
                            <div>{record.room || t("exams.labels.unknownRoom")}</div>
                            {record.campus ? (
                              <div className="mt-1 text-xs app-text-muted">{record.campus}</div>
                            ) : null}
                          </td>

                          <td className="px-4 py-3">
                            <div className="font-medium">
                              {record.studentName || t("exams.labels.unknownStudent")}
                            </div>
                            <div className="mt-1 text-xs app-text-muted">
                              {record.studentId || t("exams.labels.unknownStudentId")}
                              {record.birthDate ? ` • ${record.birthDate}` : ""}
                            </div>
                          </td>

                          <td className="px-4 py-3">
                            <div>{record.classCourse || "—"}</div>
                            {record.classStudent ? (
                              <div className="mt-1 text-xs app-text-muted">{record.classStudent}</div>
                            ) : null}
                          </td>

                          <td className="px-4 py-3">
                            <div className="text-xs app-text-muted">
                              {record.publishedAtRaw || t("exams.labels.unknownPublishTime")}
                            </div>

                            {record.attachmentName ? (
                              <div className="mt-1 text-xs app-text-muted">
                                {record.attachmentName}
                              </div>
                            ) : null}

                            <div className="mt-2 flex flex-wrap gap-2">
                              <a
                                href={record.detailUrl}
                                target="_blank"
                                rel="noreferrer"
                                className="app-btn rounded-xl px-3 py-1.5 text-xs"
                                title={t("exams.actions.openDetail")}
                              >
                                {t("exams.actions.openDetail")}
                              </a>

                              {record.attachmentUrl ? (
                                <a
                                  href={record.attachmentUrl}
                                  target="_blank"
                                  rel="noreferrer"
                                  className="app-btn rounded-xl px-3 py-1.5 text-xs"
                                  title={t("exams.actions.downloadOriginal")}
                                >
                                  {t("exams.actions.downloadOriginal")}
                                </a>
                              ) : null}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}

            {hasMoreGroups ? (
              <div className="flex justify-center">
                <button
                  type="button"
                  onClick={() => setVisibleGroupsLimit((v) => v + 8)}
                  className="app-btn-primary"
                >
                  {t("exams.actions.loadMore")}
                </button>
              </div>
            ) : null}
          </>
        )}
      </section>
    </div>
  );
}